/* From Uiverse.io by DevPTG - Tags: button */
.__UIV_SCOPE__ .chat {
  display: flex;
  position: relative;
}

.__UIV_SCOPE__ .background {
  background-color: #1950ff;
  border-radius: 50%;
  box-shadow: 0 2.1px 1.3px rgba(0, 0, 0, 0.044),
    0 5.9px 4.2px rgba(0, 0, 0, 0.054), 0 12.6px 9.5px rgba(0, 0, 0, 0.061),
    0 25px 20px rgba(0, 0, 0, 0.1);
  height: 80px;
  left: 10px;
  position: absolute;
  top: 10px;
  width: 80px;
}

.__UIV_SCOPE__ .chat-bubble {
  cursor: pointer;
  position: relative;
}

.__UIV_SCOPE__ .bubble {
  transform-origin: 50%;
  transition: transform 500ms cubic-bezier(0.17, 0.61, 0.54, 0.9);
}

.__UIV_SCOPE__ .line {
  fill: none;
  stroke: #ffffff;
  stroke-width: 2.75;
  stroke-linecap: round;
  transition: stroke-dashoffset 500ms cubic-bezier(0.4, 0, 0.2, 1);
}

.__UIV_SCOPE__ .line1 {
  stroke-dasharray: 60 90;
  stroke-dashoffset: -20;
}

.__UIV_SCOPE__ .line2 {
  stroke-dasharray: 67 87;
  stroke-dashoffset: -18;
}

.__UIV_SCOPE__ .circle {
  fill: #ffffff;
  stroke: none;
  transform-origin: 50%;
  transition: transform 500ms cubic-bezier(0.4, 0, 0.2, 1);
}

.__UIV_SCOPE__ .active .bubble {
  transform: translateX(24px) translateY(4px) rotate(45deg);
}

.__UIV_SCOPE__ .active .line1 {
  stroke-dashoffset: 21;
}

.__UIV_SCOPE__ .active .line2 {
  stroke-dashoffset: 30;
}

.__UIV_SCOPE__ .active .circle {
  transform: scale(0);
}
